import { useState } from "react";
import { TextMorph } from "@/registry/erbium/ui/text-morph";
import { Button } from "@/registry/erbium/ui/button";

export default function TextMorphExample() {
  const [count, setCount] = useState(10);

  return (
    <div className="flex items-center gap-group">
      <TextMorph aria-live="polite">{count}</TextMorph>
      <Button
        onClick={() => {
          setCount(count + 1);
        }}
      >
        Increment
      </Button>
    </div>
  );
}
